#!/usr/bin/env python3
"""s16-spear-mask.py OUT.mkv : the moving alpha mask for the red-tasselled spear between the two heads in e911 s16
(POLISH 2026-11-21, review e011 item 6). KEYS: per frame (24 fps, shot time) the spear tip's x, the tip's top y and the
left edge of Zhao's face (9999 = not near), tracked on the published final (s16 = 73.75-80.29 s, 1920x1080) by a narrow
bright run over the night sky. The box is 52 px wide around the tip, from 26 px above it down to y 540 (tassel and the
rack bar), stopped 1 px into the face edge (at c2.0-2.3 the face comes within ~13 px of the tip), feathered ~5 px.
ffv1 gray, 160 frames; edit-dh-e911-live.json vf.s16 overlays a horizontally smeared copy through it."""
import subprocess, sys
import numpy as np
KEYS = [[1052,309,9999],[1051,310,9999],[1051,310,9999],[1051,310,9999],[1051,310,9999],[1050,310,9999],[1050,310,9999],[1050,310,9999],[1050,310,9999],[1050,311,9999],[1049,311,9999],[1048,312,9999],[1048,312,9999],[1048,312,9999],[1048,313,9999],[1048,312,9999],[1046,313,9999],[1045,314,9999],[1044,314,9999],[1044,314,9999],[1040,314,9999],[1040,315,9999],[1038,315,9999],[1037,315,9999],[1034,316,1242],[1032,316,1236],[1029,316,1231],[1028,317,1230],[1024,317,1215],[1021,317,1208],[1017,317,1198],[1017,317,1197],[1011,318,1177],[1008,318,1164],[1004,319,1150],[1004,319,1150],[997,319,1122],[992,319,1105],[990,319,1089],[990,320,1090],[986,320,1062],[984,320,1050],[982,320,1040],[982,320,1039],[981,321,1022],[980,321,1013],[980,322,1007],[980,322,1007],[981,323,994],[981,324,993],[982,325,994],[982,325,994],[984,327,996],[986,328,998],[988,329,1000],[988,329,1000],[994,331,1006],[998,332,1010],[1001,333,1013],[1002,333,1014],[1006,335,1018],[1010,336,1022],[1012,337,1024],[1012,337,1024],[1016,338,1028],[1020,339,1032],[1022,339,1034],[1022,339,1034],[1024,341,1036],[1024,342,1036],[1024,342,1036],[1024,342,1036],[1025,343,1037],[1026,345,1038],[1026,345,1040],[1026,345,1040],[1026,346,1044],[1027,347,1046],[1027,347,1048],[1027,347,1048],[1028,349,1051],[1028,349,1052],[1030,350,1055],[1030,350,1055],[1032,351,1059],[1032,352,1061],[1033,353,1062],[1033,353,1062],[1034,354,1066],[1035,355,1068],[1036,356,1070],[1036,356,1070],[1038,357,1075],[1039,358,1077],[1040,359,1079],[1040,359,1079],[1044,361,1086],[1048,362,1088],[1050,362,1090],[1050,362,1090],[1052,363,1094],[1052,364,1094],[1051,365,1094],[1051,365,1094],[1049,367,1093],[1046,368,1091],[1046,369,1092],[1044,369,1092],[1042,370,1091],[1042,371,1091],[1040,372,1091],[1040,372,1091],[1037,372,1091],[1036,373,1091],[1035,374,1091],[1035,374,1091],[1034,374,1092],[1033,375,1092],[1032,375,1092],[1032,376,1092],[1030,377,1093],[1030,378,1094],[1029,378,1094],[1029,378,1094],[1028,380,1096],[1028,380,1098],[1028,380,1099],[1028,380,1099],[1028,382,1101],[1027,382,1102],[1027,383,1103],[1027,383,1103],[1026,384,1105],[1026,385,1106],[1024,386,1106],[1024,386,1106],[1021,386,1106],[1019,387,1105],[1016,388,1104],[1016,388,1104],[1012,387,1102],[1010,389,1101],[1008,389,1100],[1008,390,1100],[1004,390,1097],[1002,390,1096],[999,390,1094],[999,390,1094],[996,391,1092],[995,391,1092],[993,392,1091],[993,391,1091],[992,392,1091],[990,393,1092],[990,394,1092],[990,394,1092],[990,395,1094]]
W, H = 1920, 1080
xs = [k[0] for k in KEYS]
xs = [int(np.median(xs[max(0, i - 2):i + 3])) for i in range(len(xs))]  # 5-frame median
out = sys.argv[1]
p = subprocess.Popen(["ffmpeg", "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "gray", "-s", f"{W}x{H}", "-r", "24", "-i", "-",
                      "-vf", "gblur=sigma=2.5", "-c:v", "ffv1", "-pix_fmt", "gray", out], stdin=subprocess.PIPE)
for i in range(160):
    k = min(i, len(KEYS) - 1)
    x, ytop, face = xs[k], KEYS[k][1], KEYS[k][2]
    m = np.zeros((H, W), np.uint8)
    x0, x1 = x - 26, min(x + 26, face + 1)
    m[max(ytop - 26, 0):540, x0:x1] = 255
    p.stdin.write(m.tobytes())
p.stdin.close(); sys.exit(p.wait())
